CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_buscar_todos_cursos`(IN p_busqueda VARCHAR(255))
BEGIN
  SELECT c.id, im.datos AS emoji_datos, im.clave AS emoji_clave, c.titulo, c.descripcion, c.duracion, c.activo
  FROM cursos c
  LEFT JOIN imagenes im ON c.emoji = im.id_imagen
  WHERE c.titulo LIKE CONCAT('%', p_busqueda, '%')
  ORDER BY c.titulo ASC;
END ;;
DELIMITER ;
